function E(n,s){const d={};for(const t of n.categories)d[t.id]=0;const l={},h={},r={},a={};for(const t of s.players)l[t.id]=0,h[t.id]=0,r[t.id]=0,a[t.id]=0;let p=0,u=0,f=0;for(const t of s.matches){for(const o of t.playerIds)r[o]!==void 0&&(r[o]+=1,t.isHome&&(a[o]+=1));for(const o of t.expenses){const c=n.categories.find(e=>e.id===o.categoryId);if(c)if(p+=o.amount,d[c.id]=(d[c.id]??0)+o.amount,c.splitMode==="club")u+=o.amount;else{f+=o.amount;const e=t.playerIds.filter(i=>s.players.some(m=>m.id===i));if(e.length===0)continue;const y=o.amount/e.length;for(const i of e)l[i]+=y}}}const x=s.clubBudget??n.clubBudget,M=Math.max(0,x-u),b=Math.min(M,f),B=f>0?b/f:0;for(const t of s.players){const o=l[t.id]*B;h[t.id]=o}const P=Math.max(0,s.shuttleBudget??0),g=Object.values(a).reduce((t,o)=>t+o,0),C={};for(const t of s.players)C[t.id]=g>0?P*a[t.id]/g:0;const S=s.players.map(t=>{const o=l[t.id],c=h[t.id],e=C[t.id],y=Math.max(0,o-c)+e,i=(t.contributions??[]).reduce((I,T)=>I+(T.amount||0),0),m=(t.initialContribution||0)+i;return{playerId:t.id,name:t.name,matchesPlayed:r[t.id],homeMatchesPlayed:a[t.id],matchCost:o,clubSubsidy:c,shuttleCost:e,totalCost:y,paid:m,balance:m-y}});return{totalExpenses:p,totalByCategory:d,clubCategoryTotal:u,clubSharedSubsidy:b,clubSubsidyTotal:u+b,players:S}}const R=n=>new Intl.NumberFormat("fr-FR",{style:"currency",currency:"EUR"}).format(n);export{E as c,R as f};
